const fs = require\('fs'\);

// Read posts
let posts = JSON.parse\(fs.readFileSync\('content/posts.json', 'utf-8'\)\);

// Map images to articles by slug
const imageMap = {
  'save-money-on-car-insurance': 1,
  'best-car-insurance-to-save-money': 2,
  'best-car-insurance-in-metro-tulsa': 3
};

// Update posts with featured_media IDs
posts.forEach\(post => {
  if \(imageMap[post.slug]\) {
    post.featured_media = imageMap[post.slug];
  }
}\);

// Write back
fs.writeFileSync\('content/posts.json', JSON.stringify\(posts, null, 2\)\);

// Show results
console.log\('✅ Updated ' + posts.filter\(p => p.featured_media > 0\).length + ' articles with featured images'\);
posts.filter\(p => p.featured_media > 0\).forEach\(p => {
  console.log\('  • ' + p.title + ' → featured_media: ' + p.featured_media\);
}\);
")
